import { NextRequest, NextResponse } from 'next/server';

// Type definitions for user preferences
export interface UserPreferences {
  theme: 'light' | 'dark' | 'system';
  language: string;
  notifications: boolean;
  timezone: string;
  lastUpdated: string;
}

// Mock user preferences - in a real app, this would come from a database
const mockPreferences: UserPreferences = {
  theme: 'system',
  language: 'en',
  notifications: true,
  timezone: 'UTC',
  lastUpdated: new Date().toISOString()
};

export async function GET(request: NextRequest) {
  // In a real application, you would:
  // 1. Extract user ID from authentication headers/cookies
  // 2. Fetch user preferences from database
  // 3. Return the preferences

  // For this example, we'll simulate fetching fresh data on each request
  const freshPreferences: UserPreferences = {
    ...mockPreferences,
    lastUpdated: new Date().toISOString()
  };

  // Ensure fresh data by setting cache control headers
  const response = NextResponse.json(freshPreferences);
  response.headers.set('Cache-Control', 'no-cache, no-store, must-revalidate');
  response.headers.set('Pragma', 'no-cache');
  response.headers.set('Expires', '0');

  return response;
}

