'use client'; // Mark as client component for client-side data fetching

import { useState, useEffect } from 'react';

// Type definitions for user preferences
interface UserPreferences {
  theme: 'light' | 'dark' | 'system';
  language: string;
  notifications: boolean;
  timezone: string;
  lastUpdated: string;
}

interface UserDashboardState {
  preferences: UserPreferences | null;
  loading: boolean;
  error: string | null;
}

export default function UserDashboard() {
  const [state, setState] = useState<UserDashboardState>({
    preferences: null,
    loading: true,
    error: null
  });

  // Function to fetch user preferences with cache-busting
  const fetchUserPreferences = async () => {
    try {
      setState(prev => ({ ...prev, loading: true, error: null }));

      // Add cache-busting parameter to ensure fresh data on each request
      const timestamp = Date.now();
      const response = await fetch(`/api/user/preferences?t=${timestamp}`, {
        method: 'GET',
        headers: {
          'Cache-Control': 'no-cache, no-store, must-revalidate',
          'Pragma': 'no-cache',
          'Expires': '0'
        }
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      setState(prev => ({ 
        ...prev, 
        preferences: data, 
        loading: false 
      }));
    } catch (error) {
      console.error('Error fetching user preferences:', error);
      setState(prev => ({ 
        ...prev, 
        error: 'Failed to fetch user preferences', 
        loading: false 
      }));
    }
  };

  // Fetch data on component mount and set up polling for real-time updates
  useEffect(() => {
    fetchUserPreferences();

    // Optional: Set up polling to refresh data every 30 seconds
    const interval = setInterval(fetchUserPreferences, 30000);

    return () => {
      clearInterval(interval);
    };
  }, []);

  // Manual refresh handler
  const handleRefresh = () => {
    fetchUserPreferences();
  };

  if (state.loading && !state.preferences) {
    return (
      <div className="user-dashboard">
        <h2>User Dashboard</h2>
        <div className="loading">Loading user preferences...</div>
      </div>
    );
  }

  if (state.error) {
    return (
      <div className="user-dashboard">
        <h2>User Dashboard</h2>
        <div className="error">
          {state.error}
          <button onClick={handleRefresh} className="retry-btn">
            Retry
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="user-dashboard">
      <h2>User Dashboard</h2>

      <div className="dashboard-content">
        <div className="preferences-section">
          <h3>User Preferences</h3>

          <div className="preference-item">
            <span className="label">Theme:</span>
            <span className="value">{state.preferences?.theme}</span>
          </div>

          <div className="preference-item">
            <span className="label">Language:</span>
            <span className="value">{state.preferences?.language}</span>
          </div>

          <div className="preference-item">
            <span className="label">Notifications:</span>
            <span className="value">
              {state.preferences?.notifications ? 'Enabled' : 'Disabled'}
            </span>
          </div>

          <div className="preference-item">
            <span className="label">Timezone:</span>
            <span className="value">{state.preferences?.timezone}</span>
          </div>

          <div className="preference-item">
            <span className="label">Last Updated:</span>
            <span className="value">
              {new Date(state.preferences!.lastUpdated).toLocaleString()}
            </span>
          </div>
        </div>

        <div className="actions">
          <button onClick={handleRefresh} className="refresh-btn">
            Refresh Data
          </button>
          <p className="note">
            Data is fetched fresh on each request to ensure accuracy
          </p>
        </div>
      </div>
    </div>
  );
}

